mapper.insert:
  BEGIN

  		 DELETE T_ECC_AUTHORITY_GROUP WHERE ROLE_ID = #{sp.roleId} AND SHARE_ID = #{shareId};
  		 INSERT INTO T_ECC_AUTHORITY_GROUP(
  		 	AUTH_ID,
  		 	ROLE_ID,
  		 	SHARE_ID
 		 )VALUES(
  		 	ECC_IBF_GET_SEQNO(TO_CHAR(SYSDATE, 'YYYYMMDD')),
  		 	#{sp.roleId},
  		 	#{shareId}
		 );

  END;

mapper.select:
		 SELECT SHARE_ID AS ROLE_ID
          FROM T_ECC_AUTHORITY_GROUP TAG,
               T_ROLE TR
         WHERE TAG.SHARE_ID=TR.ROLE_ID
           AND TR.ROLE_TYPE =#{dataType}   
           AND TR.AUTHORITY_TYPE = '1'   
    START WITH TAG.ROLE_ID = #{roleId}
    CONNECT BY NOCYCLE PRIOR TAG.SHARE_ID = TAG.ROLE_ID
           AND TR.ROLE_TYPE = #{dataType}
